#!/usr/bin/env python3
"""Review generic sign14 absdiff transport candidate without invoking Lean."""
import hashlib,json,re,subprocess,sys
from pathlib import Path
assert sys.flags.isolated and sys.flags.no_site
root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign14-rank-value-check';draft=root/'research/nine-sharing-sign14-rank-value-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='7c80a0c4c207cbb2d81186463273f226dfcf541efb0469c4b1a40ecc32d0b955' and sha(m)=='972d7eb8c3df44565ef7b0703e844f5c80e8d2a94716daa7c380657f3aee067f';row,=json.loads(m.read_text())['rows'];name='Sign14RankValue';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256']=='aeab58e2dff19ec982c543a785f2d8e890ccd631326c2226ed94a1dad98deb26' and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign14SharedValues'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
assert 'theorem rank_eval (p : Fin 4 → ℤ) (beta MC MF : V) (v : Fin 15 → V)' in s and all('(hp'+i+' : ((p '+i+' : ℤ) : DiffRing V) = ι ' in s for i in ('0','2','3')) and '(hqF : v 2 + 1 ≤ A beta v)' in s and '(shared27 p).evalRing' in s and '(shared14 p).evalRing' in s and 'ι (Rank beta MC MF v)' in s
r=run.read_text();assert "'-M2800'" in r and "'-j1'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r and 'free>=5_000_000_000' in r and 'matches=[x for x in base[\'rows\'] if x[\'module\']==local]' in r and "sha(P/'source-manifest.json')" in r
check=root/'reviews/nine-sharing-sign14-shared-values-terminal-independent/check.py';assert sha(check)=='f79ee2ca9bc5495b647228b946e63c0ca84afc143cd1acd310420c3594d28096';subprocess.run([sys.executable,'-I','-S','-B',str(check)],capture_output=True,check=True,timeout=120)
x=subprocess.run([sys.executable,'-I','-S','-B',str(run),'--preflight'],capture_output=True,text=True,timeout=180);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','runner_sha256':sha(run),'scope':'source-only rank representation conditional on represented ports and q ≥ F; no natural lift or bridge'},indent=2,sort_keys=True))
